=== #55 zimmButton.tsx — how does it style? ===
import React, {type CSSProperties, useState} from 'react'
import {colors, spacing, textStyles, actionSizes, borderWidths, motion} from 'app/theme/foundation'
import {ZimmIcon} from './zimmIcon'
import type {ZimmIconType} from './zimmIcon'

type ZimmButtonVisualState = {background: string; colour: string; borderColour: string}

// Mirrors tokens/buttons.css 1:1 (default/hover/disabled per variant + light/inverse mode).
const STATES: Record<'primary' | 'secondary', Record<'light' | 'inverse', Record<'default' | 'hover' | 'disabled', ZimmButtonVisualState>>> = {
    primary: {
        light: {
            default:  {background: colors.action.primary.bgDefault,  colour: colors.action.primary.text,         borderColour: 'transparent'},
            hover:    {background: colors.action.primary.bgHover,    colour: colors.action.primary.text,         borderColour: 'transparent'},
            disabled: {background: colors.action.primary.bgDisabled, colour: colors.action.primary.textDisabled, borderColour: 'transparent'},
        },
        inverse: {
            default:  {background: colors.action.primary.text,       colour: colors.action.primary.bgDefault,    borderColour: 'transparent'},
            hover:    {background: colors.action.secondary.bgHover,  colour: colors.action.primary.bgDefault,    borderColour: 'transparent'},
            disabled: {background: colors.action.primary.bgDisabled, colour: colors.action.primary.textDisabled, borderColour: 'transparent'},
        },
    },
    secondary: {
        light: {
            default:  {background: 'transparent',                   colour: colors.action.secondary.text,         borderColour: colors.action.secondary.border},
            hover:    {background: colors.action.secondary.bgHover, colour: colors.action.secondary.text,         borderColour: colors.action.secondary.border},
            disabled: {background: 'transparent',                   colour: colors.action.secondary.textDisabled, borderColour: colors.action.secondary.textDisabled},
        },
        inverse: {
            default:  {background: 'transparent',                   colour: colors.action.primary.text,           borderColour: colors.action.primary.text},
            hover:    {background: colors.action.secondary.bgHover, colour: colors.action.primary.text,           borderColour: colors.action.primary.text},
            disabled: {background: 'transparent',                   colour: colors.action.secondary.textDisabled, borderColour: colors.action.secondary.textDisabled},
        },
    },
}

// Pressed/active is identical across variant + inverse per Figma (node 901:2897) — see
// tokens/buttons.css comment.
const PRESSED: Record<'primary' | 'secondary', ZimmButtonVisualState> = {
    primary:   {background: colors.action.primary.bgPressed, colour: colors.action.primary.text, borderColour: 'transparent'},
    secondary: {background: colors.action.primary.bgPressed, colour: colors.action.primary.text, borderColour: colors.action.primary.bgPressed},
}

type ZimmButtonBaseProps = {
    /** Visible label (primary/secondary) or aria-label (icon variant has no visible text). */
    label: string
    type?: 'button' | 'submit' | 'reset'
    disabled?: boolean
    inverse?: boolean
    onClick?: () => void
    style?: CSSProperties
}

type ZimmLabelButtonProps = ZimmButtonBaseProps & {
    variant?: 'primary' | 'secondary'
    size?: 'large' | 'medium'
    fullWidth?: boolean
}

type ZimmIconButtonProps = ZimmButtonBaseProps & {
    variant: 'icon'
    icon: ZimmIconType
    size?: 12 | 16 | 20
}

type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps

/** Atom — labelled button (primary/secondary) or icon-only button. Mirrors zimm-button contract. */
export const ZimmButton = (props: ZimmButtonProps) => {
    const {label, type = 'button', disabled = false, inverse = false, onClick, style} = props


