################ Han's zimm-button/index.tsx ################
import React from 'react'
import { Global } from '@emotion/react'
import { zimmButtonStyles } from './zimm-button.styles'
import { iconUrl } from '../../assets/iconUrls'
import type { ZimmIconType } from '../../assets/iconUrls'

export type { ZimmIconType }

export type ZimmButtonProps = {
  /** Visual variant — primary (filled), secondary (outlined), or icon-only */
  variant?: 'primary' | 'secondary' | 'icon'
  /** Size step — large (52px, default) or medium (40px). Ignored for variant=icon */
  size?: 'large' | 'medium'
  /** Button label text. For variant=icon, becomes aria-label */
  label?: string
  /** Icon name from the Zimmermann icon set. Required when variant=icon */
  icon?: ZimmIconType
  /** Native button type */
  type?: 'button' | 'submit' | 'reset'
  /** Disables the button */
  disabled?: boolean
  /** Inverse mode — white/light styles for use on dark backgrounds */
  inverse?: boolean
  /** Stretches the button to full container width. Ignored for variant=icon */
  fullWidth?: boolean
  /** Click handler */
  onClick?: React.MouseEventHandler<HTMLButtonElement>
}

/**
 * Zimmermann button atom. Renders a native `<button>` with three visual variants:
 * primary (filled), secondary (outlined), and icon (icon-only square hit area).
 *
 * Consumer contract: the component inherits CSS `color` from its parent only for the
 * icon variant — set `color` on a wrapper to control icon stroke colour in that context.
 */
export function ZimmButton({
  variant = 'primary',
  size = 'large',
  label = 'Button',
  icon,
  type = 'button',
  disabled = false,
  inverse = false,
  fullWidth = false,

################ zimm-button.styles.ts (first 40) ################
import { css } from '@emotion/react'

export const zimmButtonStyles = css`
  /* ---- Label variants (primary/secondary): shared structural rules ---- */

  .zimm-btn {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--zimm-size-action-gap);
    min-width: 80px;
    overflow: clip;
    cursor: pointer;
    font-family: var(--zimm-font-family-body);
    font-weight: var(--zimm-font-weight-medium);
    text-transform: uppercase;
    letter-spacing: var(--zimm-font-letterspacing-sm);
    transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  }

  .zimm-btn-full {
    display: flex;
    width: 100%;
  }

  .zimm-btn-large {
    height: var(--zimm-size-action-height-lg);
    padding: 0 var(--zimm-size-action-padding-h-lg);
    font-size: var(--zimm-font-size-2xs);
    line-height: var(--zimm-font-lineheight-3xs);
  }

  .zimm-btn-medium {
    height: var(--zimm-size-action-height-md);
    padding: 0 var(--zimm-size-action-padding-h-md);
    font-size: var(--zimm-font-size-3xs);
    line-height: var(--zimm-font-lineheight-2xs);
  }

