cat > overrides/app/hooks/useZimmTextInputState.test.ts <<'TSEOF'
import { describe, test, expect, vi } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { cssVars } from '../utils/cssVars';
import { useZimmTextInputState } from './useZimmTextInputState';

/**
 * The value-ownership switch and the derived-colour cascade are the two things in this
 * hook that can break without surfacing as a type or build error: a controlled input
 * that silently keeps its own state looks correct until a parent form tries to reset it,
 * and a mis-ordered colour branch renders a plausible-but-wrong border.
 */

const base = { inverse: false, disabled: false, hasError: false };

const change = (v: string) =>
  ({ target: { value: v } }) as unknown as React.ChangeEvent<HTMLInputElement>;

describe('useZimmTextInputState — value ownership', () => {
  test('is uncontrolled by default and starts empty', () => {
    const { result } = renderHook(() => useZimmTextInputState(base));
    expect(result.current.value).toBe('');
  });

  test('seeds the uncontrolled value from defaultValue', () => {
    const { result } = renderHook(() => useZimmTextInputState({ ...base, defaultValue: 'seed' }));
    expect(result.current.value).toBe('seed');
  });

  test('uncontrolled: a change updates the value and notifies the caller', () => {
    const onChange = vi.fn();
    const { result } = renderHook(() => useZimmTextInputState({ ...base, onChange }));

    act(() => result.current.handleChange(change('hello')));

    expect(result.current.value).toBe('hello');
    expect(onChange).toHaveBeenCalledWith('hello');
  });

  test('uncontrolled: clearing resets the value and notifies with an empty string', () => {
    const onChange = vi.fn();
    const { result } = renderHook(() =>
      useZimmTextInputState({ ...base, defaultValue: 'x', onChange }),
    );

    act(() => result.current.handleClear());

    expect(result.current.value).toBe('');
    expect(onChange).toHaveBeenCalledWith('');
  });

  test('controlled: the value comes from the prop, not internal state', () => {
    const { result } = renderHook(() => useZimmTextInputState({ ...base, value: 'owned' }));
    expect(result.current.value).toBe('owned');
  });

  test('controlled: a change notifies the caller but does not move the value itself', () => {
    const onChange = vi.fn();
    const { result } = renderHook(() =>
      useZimmTextInputState({ ...base, value: 'owned', onChange }),
    );

    act(() => result.current.handleChange(change('typed')));

    // The parent owns the value — it only moves when the parent re-renders with a new prop.
    expect(result.current.value).toBe('owned');
    expect(onChange).toHaveBeenCalledWith('typed');
  });

  test('controlled: defaultValue is ignored', () => {
    const { result } = renderHook(() =>
      useZimmTextInputState({ ...base, value: 'owned', defaultValue: 'ignored' }),
    );
    expect(result.current.value).toBe('owned');
  });

  test('controlled: a new prop value is reflected on re-render', () => {
    const { result, rerender } = renderHook(
      ({ value }) => useZimmTextInputState({ ...base, value }),
      { initialProps: { value: 'first' } },
    );

    rerender({ value: 'second' });

    expect(result.current.value).toBe('second');
  });
});

describe('useZimmTextInputState — floated label', () => {
  test('floats when the field has a value', () => {
    const { result } = renderHook(() => useZimmTextInputState({ ...base, value: 'v' }));
    expect(result.current.floated).toBe(true);
  });

  test('floats while focused even when empty', () => {
    const { result } = renderHook(() => useZimmTextInputState(base));
    expect(result.current.floated).toBe(false);

    act(() => result.current.setFocused(true));

    expect(result.current.floated).toBe(true);
  });
});

describe('useZimmTextInputState — derived border colour precedence', () => {
  test('disabled wins over error and focus', () => {
    const { result } = renderHook(() =>
      useZimmTextInputState({ ...base, disabled: true, hasError: true, value: 'v' }),
    );
    expect(result.current.borderColour).toBe(cssVars.color.border.forms);
  });

  test('error wins over focus and filled', () => {
    const { result } = renderHook(() =>
      useZimmTextInputState({ ...base, hasError: true, value: 'v' }),
    );
    expect(result.current.borderColour).toBe(cssVars.color.border.error);
  });

  test('a filled but unfocused field darkens to the focus colour', () => {
    const { result } = renderHook(() => useZimmTextInputState({ ...base, value: 'v' }));
    expect(result.current.borderColour).toBe(cssVars.color.border.focus);
  });

  test('an empty, unfocused, valid field uses the default border', () => {
    const { result } = renderHook(() => useZimmTextInputState(base));
    expect(result.current.borderColour).toBe(cssVars.color.border.forms);
  });

  test('hover keeps the error colour when in error, otherwise darkens', () => {
    const { result: errored } = renderHook(() =>
      useZimmTextInputState({ ...base, hasError: true }),
    );
    expect(errored.current.hoverBorderColour).toBe(cssVars.color.border.error);

    const { result: valid } = renderHook(() => useZimmTextInputState(base));
    expect(valid.current.hoverBorderColour).toBe(cssVars.color.border.focus);
  });

  test('inverse mode uses the inverse palette', () => {
    const { result } = renderHook(() => useZimmTextInputState({ ...base, inverse: true }));
    expect(result.current.borderColour).toBe(cssVars.color.text.inverse);

    const { result: erroredInverse } = renderHook(() =>
      useZimmTextInputState({ ...base, inverse: true, hasError: true }),
    );
    expect(erroredInverse.current.borderColour).toBe(cssVars.color.status.errorBackground);
  });
});

describe('useZimmTextInputState — derived label colour', () => {
  test('light mode: subtle once floated, default otherwise', () => {
    const { result: floated } = renderHook(() => useZimmTextInputState({ ...base, value: 'v' }));
    expect(floated.current.labelColour).toBe(cssVars.color.text.secondary);

    const { result: resting } = renderHook(() => useZimmTextInputState(base));
    expect(resting.current.labelColour).toBe(cssVars.color.text.default);
  });

  test('inverse mode: grey once floated, white otherwise', () => {
    const { result: floated } = renderHook(() =>
      useZimmTextInputState({ ...base, inverse: true, value: 'v' }),
    );
    expect(floated.current.labelColour).toBe(cssVars.color.text.inverseGrey);

    const { result: resting } = renderHook(() =>
      useZimmTextInputState({ ...base, inverse: true }),
    );
    expect(resting.current.labelColour).toBe(cssVars.color.text.inverse);
  });

  test('disabled uses the subtle colour for the mode', () => {
    const { result: light } = renderHook(() => useZimmTextInputState({ ...base, disabled: true }));
    expect(light.current.labelColour).toBe(cssVars.color.text.secondary);

    const { result: inverse } = renderHook(() =>
      useZimmTextInputState({ ...base, disabled: true, inverse: true }),
    );
    expect(inverse.current.labelColour).toBe(cssVars.color.text.inverseGrey);
  });
});
TSEOF
